package com.jobradar.taxonomy.role;
import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface RoleRepository extends JpaRepository<RoleEntity,Integer> { @Query("select r from RoleEntity r where r.active=true and r.category.active=true and (:cat is null or r.category.id=:cat) and (:q is null or lower(r.roleName) like lower(concat('%',cast(:q as String),'%')))") Page<RoleEntity> browse(@Param("q") String q,@Param("cat") Integer cat,Pageable p); Optional<RoleEntity> findBySlugIgnoreCaseAndActiveTrue(String slug); boolean existsByCategoryIdAndActiveTrue(Integer categoryId); boolean existsByRoleNameIgnoreCase(String n); boolean existsBySlugIgnoreCase(String s); boolean existsByRoleNameIgnoreCaseAndIdNot(String n,Integer id); boolean existsBySlugIgnoreCaseAndIdNot(String s,Integer id); }
